CW = 205
x, y, k = "<i>x</i>", "<i>y</i>", "<i>k</i>"


def S(title, problems, intro=None, cols=2):
    return Section(title, problems, intro, cols)


def money(v):
    return f"${v:,.2f}"


def tbl(t, head, rows, w=None):
    data = [head] + rows
    n = len(head)
    return table(t, data, [w or (0.75 * inch)] * n, width=(w or 0.75 * inch) * n)


